Wave shader specifics:

vertex:
uniform float uTime;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vH;
float wave(vec2 p, float t) {...}
void main(){
 vec3 pos = position;
 float h = wave(pos.xz, uTime);
 pos.y += h;
 float e = 0.35;
 float hx = wave(pos.xz + vec2(e,0.0), uTime) - wave(pos.xz - vec2(e,0.0), uTime);
 float hz = wave(pos.xz + vec2(0.0,e), uTime) - wave(pos.xz - vec2(0.0,e), uTime);
 vec3 n = normalize(vec3(-hx, 2.0*e, -hz));
 vec4 wp = modelMatrix * vec4(pos,1.0);
 vWorldPos = wp.xyz;
 vNormalW = normalize(mat3(modelMatrix) * n);
 vH = h;
 gl_Position = projectionMatrix * viewMatrix * wp;
}

fragment:
uniform float uTime; uniform vec3 uSunDir, uDeep, uShallow, uFoam, uHorizon; varying...
float crestNoise(vec2 p,float t){...}
void main(){
 vec3 N = normalize(vNormalW);
 vec3 V = normalize(cameraPosition - vWorldPos);
 float fres = pow(1.0 - max(dot(N,V),0.0), 3.0);
 float heightMix = smoothstep(-1.5, 1.5, vH);
 vec3 water = mix(uDeep, uShallow, clamp(heightMix*0.65 + 0.15,0,1));
 // sky reflection color based on N and view
 float upness = N.y;
 vec3 skyRef = mix(vec3(1.0,0.80,0.55), vec3(0.38,0.68,0.82), smoothstep(0.0,0.5,upness*0.5+0.5));
 water = mix(water, skyRef, fres*0.5);
 float diff = max(dot(N, uSunDir),0.0);
 water += vec3(1.0,0.78,0.48) * diff * 0.12;
 // specular
 vec3 H = normalize(uSunDir + V);
 float spec = pow(max(dot(N,H),0.0), 160.0);
 water += vec3(1.0,0.86,0.6)*spec*2.2;
 // foam at crests and streaks
 float n = sin(vWorldPos.x*2.7 + uTime*1.3 + sin(vWorldPos.z*1.9 - uTime*0.9)*2.0)
         * sin(vWorldPos.z*3.1 - uTime*1.1);
 float crest = smoothstep(0.55, 1.45, vH + n*0.18);
 float lace = smoothstep(0.75, 1.0, sin(vWorldPos.x*1.4 + vWorldPos.z*2.2 + uTime*0.7)*0.5+0.5) * smoothstep(0.2,1.2,vH);
 float foam = crest*0.75 + lace*0.18*crest;
 water = mix(water, uFoam, clamp(foam,0.0,1.0)*0.75);
 // distance fog
 float dist = length(cameraPosition - vWorldPos);
 float fog = 1.0 - exp(-pow(dist*0.0032, 1.6));
 water = mix(water, uHorizon, clamp(fog,0.0,1.0));
 gl_FragColor = vec4(water, 1.0);
}

