import * as THREE from "three";

// CPU mirror of the GLSL wave function, used to keep the board on the surface.
export function waveHeight(x, z, t) {
  let h = 0;
  h += Math.sin(x * 0.16 + t * 0.9) * Math.cos(z * 0.12 + t * 0.7) * 1.05;
  h += Math.sin((x + z) * 0.21 - t * 1.25) * 0.55;
  h += Math.sin(x * 0.45 - z * 0.3 + t * 2.0) * 0.18;
  h += Math.sin(x * 0.9 + z * 0.6 + t * 2.8) * 0.07;
  return h;
}

export function waveNormal(x, z, t) {
  const e = 0.35;
  const hx = waveHeight(x + e, z, t) - waveHeight(x - e, z, t);
  const hz = waveHeight(x, z + e, t) - waveHeight(x, z - e, t);
  return new THREE.Vector3(-hx, 2 * e, -hz).normalize();
}

const vertexShader = /* glsl */ `
uniform float uTime;
varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vH;

float wave(vec2 p, float t) {
  float h = 0.0;
  h += sin(p.x * 0.16 + t * 0.9) * cos(p.y * 0.12 + t * 0.7) * 1.05;
  h += sin((p.x + p.y) * 0.21 - t * 1.25) * 0.55;
  h += sin(p.x * 0.45 - p.y * 0.3 + t * 2.0) * 0.18;
  h += sin((p.x * 0.9 + p.y * 0.6) + t * 2.8) * 0.07;
  return h;
}

void main() {
  vec3 pos = position;
  float h = wave(pos.xz, uTime);
  pos.y += h;

  float e = 0.35;
  float hx = wave(pos.xz + vec2(e, 0.0), uTime) - wave(pos.xz - vec2(e, 0.0), uTime);
  float hz = wave(pos.xz + vec2(0.0, e), uTime) - wave(pos.xz - vec2(0.0, e), uTime);
  vec3 n = normalize(vec3(-hx, 2.0 * e, -hz));

  vec4 wp = modelMatrix * vec4(pos, 1.0);
  vWorldPos = wp.xyz;
  vNormalW = normalize(mat3(modelMatrix) * n);
  vH = h;

  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const fragmentShader = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform vec3 uFoam;
uniform vec3 uHorizon;

varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vH;

void main() {
  vec3 N = normalize(vNormalW);
  vec3 V = normalize(cameraPosition - vWorldPos);

  float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);
  float heightMix = smoothstep(-1.5, 1.4, vH);

  vec3 water = mix(uDeep, uShallow, clamp(heightMix * 0.7 + 0.12, 0.0, 1.0));

  vec3 skyRef = mix(vec3(1.0, 0.79, 0.54), vec3(0.42, 0.71, 0.84),
                    smoothstep(-0.4, 0.65, N.y));
  water = mix(water, skyRef, fres * 0.55);

  float diff = max(dot(N, uSunDir), 0.0);
  water += vec3(1.0, 0.78, 0.48) * diff * 0.13;

  vec3 H = normalize(uSunDir + V);
  float spec = pow(max(dot(N, H), 0.0), 170.0);
  water += vec3(1.0, 0.86, 0.6) * spec * 2.4;

  float ripple = sin(vWorldPos.x * 2.7 + uTime * 1.3 + sin(vWorldPos.z * 1.9 - uTime * 0.9) * 2.0)
               * sin(vWorldPos.z * 3.1 - uTime * 1.1);
  float crest = smoothstep(0.42, 1.4, vH + ripple * 0.2);
  float lace = smoothstep(0.62, 1.0, sin(vWorldPos.x * 1.4 + vWorldPos.z * 2.2 + uTime * 0.7) * 0.5 + 0.5);
  float foam = crest * 0.7 + lace * 0.22 * crest;
  water = mix(water, uFoam, clamp(foam, 0.0, 1.0) * 0.8);

  float dist = length(cameraPosition - vWorldPos);
  float fog = 1.0 - exp(-pow(dist * 0.0034, 1.7));
  water = mix(water, uHorizon, clamp(fog, 0.0, 1.0));

  gl_FragColor = vec4(water, 1.0);
}
`;

export function createOcean() {
  const geometry = new THREE.PlaneGeometry(520, 520, 340, 340);
  geometry.rotateX(-Math.PI / 2);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uSunDir: { value: new THREE.Vector3(-0.4, 0.26, -0.88).normalize() },
      uDeep: { value: new THREE.Color("#0a4659") },
      uShallow: { value: new THREE.Color("#168394") },
      uFoam: { value: new THREE.Color("#f8efe0") },
      uHorizon: { value: new THREE.Color("#e9c8a5") },
    },
    vertexShader,
    fragmentShader,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;

  return {
    mesh,
    update(t) {
      material.uniforms.uTime.value = t;
    },
  };
}

import * as THREE from "three";

const white = new THREE.MeshStandardMaterial({
  color: "#f8f3e6",
  roughness: 0.62,
  metalness: 0.02,
});
const cream = new THREE.MeshStandardMaterial({
  color: "#efe4cf",
  roughness: 0.7,
});
const grey = new THREE.MeshStandardMaterial({
  color: "#cfd0c8",
  roughness: 0.7,
});
const orange = new THREE.MeshStandardMaterial({
  color: "#f5a13c",
  roughness: 0.46,
});
const pouchMat = new THREE.MeshStandardMaterial({
  color: "#ea8434",
  roughness: 0.5,
});
const dark = new THREE.MeshStandardMaterial({
  color: "#241f1b",
  roughness: 0.35,
});
const gold = new THREE.MeshStandardMaterial({
  color: "#e0ac52",
  roughness: 0.22,
  metalness: 0.85,
});
const lens = new THREE.MeshStandardMaterial({
  color: "#12252c",
  roughness: 0.08,
  metalness: 0.65,
});
const boardMat = new THREE.MeshStandardMaterial({
  color: "#ff6d4a",
  roughness: 0.38,
  metalness: 0.05,
});
const stripeMat = new THREE.MeshStandardMaterial({
  color: "#fff0cf",
  roughness: 0.42,
});
const tealMat = new THREE.MeshStandardMaterial({
  color: "#0f7c82",
  roughness: 0.35,
});

function roundedRectShape(halfW, halfH, r) {
  const s = new THREE.Shape();
  s.moveTo(-halfW + r, -halfH);
  s.lineTo(halfW - r, -halfH);
  s.quadraticCurveTo(halfW, -halfH, halfW, -halfH + r);
  s.lineTo(halfW, halfH - r);
  s.quadraticCurveTo(halfW, halfH, halfW - r, halfH);
  s.lineTo(-halfW + r, halfH);
  s.quadraticCurveTo(-halfW, halfH, -halfW, halfH - r);
  s.lineTo(-halfW, -halfH + r);
  s.quadraticCurveTo(-halfW, -halfH, -halfW + r, -halfH);
  return s;
}

function cylinderBetween(a, b, radius, material, radialSegments = 12) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(radius, radius * 1.05, len, radialSegments);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

function makeWingShape() {
  const s = new THREE.Shape();
  s.moveTo(0, 0);
  s.quadraticCurveTo(0.34, -0.07, 0.68, -0.03);
  s.quadraticCurveTo(0.9, 0.01, 1.04, 0.13);
  s.lineTo(0.95, 0.21);
  s.quadraticCurveTo(0.86, 0.13, 0.79, 0.38);
  s.quadraticCurveTo(0.69, 0.2, 0.57, 0.45);
  s.quadraticCurveTo(0.46, 0.25, 0.31, 0.4);
  s.quadraticCurveTo(0.18, 0.2, 0.04, 0.17);
  s.lineTo(0, 0);
  return s;
}

function createWing(side) {
  // side: +1 = camera side, -1 = far side
  const outer = new THREE.Group();
  outer.position.set(0.08, 1.9, 0.48 * side);

  const span = new THREE.Vector3(0.28, 0.5, 0.92 * side).normalize();
  const chord = new THREE.Vector3(-1, -0.16, 0.04 * side).normalize();
  const normal = new THREE.Vector3().crossVectors(span, chord).normalize();
  const basis = new THREE.Matrix4().makeBasis(span, chord, normal);
  outer.quaternion.setFromRotationMatrix(basis);

  const inner = new THREE.Group();
  outer.add(inner);

  const shape = makeWingShape();
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.055,
    bevelEnabled: true,
    bevelThickness: 0.018,
    bevelSize: 0.018,
    bevelSegments: 2,
    curveSegments: 16,
  });
  geo.translate(0, 0, -0.027);

  const mesh = new THREE.Mesh(geo, white);
  mesh.material = white.clone();
  mesh.material.side = THREE.DoubleSide;
  mesh.scale.set(1.32, 1.24, 1);
  inner.add(mesh);

  // A smaller grey-blue layer suggests the primary feathers underneath.
  const under = new THREE.Mesh(geo.clone(), grey.clone());
  under.material.side = THREE.DoubleSide;
  under.material.color.set("#b9c6c6");
  under.scale.set(1.0, 0.9, 1);
  under.position.set(0.12, 0.05, -0.05 * side);
  under.material.transparent = true;
  under.material.opacity = 0.55;
  inner.add(under);

  return { outer, inner };
}

export function createSurfer() {
  const group = new THREE.Group();

  // ---------- surfboard ----------
  const boardShape = new THREE.Shape();
  boardShape.moveTo(-2.15, -0.6);
  boardShape.quadraticCurveTo(-2.38, 0, -2.15, 0.6);
  boardShape.quadraticCurveTo(-0.5, 0.82, 1.15, 0.72);
  boardShape.quadraticCurveTo(1.98, 0.56, 2.5, 0);
  boardShape.quadraticCurveTo(1.98, -0.56, 1.15, -0.72);
  boardShape.quadraticCurveTo(-0.5, -0.82, -2.15, -0.6);

  const boardGeo = new THREE.ExtrudeGeometry(boardShape, {
    depth: 0.12,
    bevelEnabled: true,
    bevelThickness: 0.035,
    bevelSize: 0.035,
    bevelSegments: 4,
    curveSegments: 28,
  });
  boardGeo.rotateX(-Math.PI / 2);
  const board = new THREE.Mesh(boardGeo, boardMat);
  board.position.y = -0.075;
  group.add(board);

  const stripeShape = new THREE.Shape();
  stripeShape.moveTo(-1.82, -0.14);
  stripeShape.quadraticCurveTo(-1.98, 0, -1.82, 0.14);
  stripeShape.quadraticCurveTo(-0.2, 0.26, 1.35, 0.24);
  stripeShape.quadraticCurveTo(1.86, 0.2, 2.16, 0);
  stripeShape.quadraticCurveTo(1.86, -0.2, 1.35, -0.24);
  stripeShape.quadraticCurveTo(-0.2, -0.26, -1.82, -0.14);
  const stripeGeo = new THREE.ExtrudeGeometry(stripeShape, {
    depth: 0.008,
    bevelEnabled: false,
    curveSegments: 24,
  });
  stripeGeo.rotateX(-Math.PI / 2);
  const stripe = new THREE.Mesh(stripeGeo, stripeMat);
  stripe.position.y = 0.073;
  group.add(stripe);

  // thin teal pin-lines either side of the cream stripe
  for (const z of [-0.27, 0.27]) {
    const pin = new THREE.Mesh(new THREE.BoxGeometry(3.6, 0.006, 0.025), tealMat);
    pin.position.set(-0.1, 0.079, z);
    pin.scale.x = 0.95;
    group.add(pin);
  }

  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.lineTo(-0.58, 0);
  finShape.quadraticCurveTo(-0.62, -0.42, -0.42, -0.62);
  finShape.lineTo(-0.26, -0.3);
  finShape.lineTo(0, 0);
  const finGeo = new THREE.ExtrudeGeometry(finShape, {
    depth: 0.045,
    bevelEnabled: true,
    bevelThickness: 0.01,
    bevelSize: 0.01,
    bevelSegments: 2,
  });
  const fin = new THREE.Mesh(finGeo, tealMat);
  fin.position.set(-1.45, -0.05, -0.022);
  group.add(fin);

  // soft contact shadow on the deck
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(1, 32),
    new THREE.MeshBasicMaterial({
      color: "#7d3a25",
      transparent: true,
      opacity: 0.22,
      depthWrite: false,
    })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(1.05, 0.58, 1);
  shadow.position.set(0.02, 0.084, 0);
  group.add(shadow);

  // ---------- pelican ----------
  const pelican = new THREE.Group();
  pelican.position.y = 0.08;
  group.add(pelican);

  const body = new THREE.Mesh(new THREE.SphereGeometry(1, 40, 28), white);
  body.scale.set(1.02, 0.69, 0.62);
  body.position.set(0.05, 1.58, 0);
  body.rotation.z = -0.08;
  pelican.add(body);

  const chest = new THREE.Mesh(new THREE.SphereGeometry(1, 32, 24), white);
  chest.scale.set(0.54, 0.55, 0.5);
  chest.position.set(0.52, 1.52, 0);
  pelican.add(chest);

  const rump = new THREE.Mesh(new THREE.SphereGeometry(1, 28, 22), cream);
  rump.scale.set(0.56, 0.48, 0.5);
  rump.position.set(-0.66, 1.6, 0);
  pelican.add(rump);

  // neck
  const neckCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0.4, 1.9, 0),
    new THREE.Vector3(0.66, 2.14, 0),
    new THREE.Vector3(0.68, 2.42, 0),
    new THREE.Vector3(0.9, 2.65, 0),
  ]);
  const neck = new THREE.Mesh(new THREE.TubeGeometry(neckCurve, 24, 0.185, 12, false), white);
  pelican.add(neck);

  const headGroup = new THREE.Group();
  pelican.add(headGroup);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.36, 36, 26), white);
  head.scale.set(1.02, 0.96, 0.9);
  head.position.set(1.02, 2.76, 0);
  headGroup.add(head);

  // upper mandible
  const beak = new THREE.Mesh(new THREE.ConeGeometry(0.205, 1.36, 18), orange);
  beak.geometry.rotateZ(-Math.PI / 2);
  beak.scale.set(1, 0.56, 0.9);
  beak.position.set(2.0, 2.72, 0);
  beak.rotation.z = -0.055;
  headGroup.add(beak);

  const beakTip = new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 12), pouchMat);
  beakTip.scale.set(1.4, 0.8, 0.9);
  beakTip.position.set(2.66, 2.69, 0);
  headGroup.add(beakTip);

  // characteristic throat pouch
  const pouch = new THREE.Mesh(new THREE.SphereGeometry(1, 30, 20), pouchMat);
  pouch.scale.set(0.56, 0.24, 0.24);
  pouch.position.set(1.8, 2.55, 0);
  pouch.rotation.z = 0.06;
  headGroup.add(pouch);

  const pouchRidge = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 16), orange);
  pouchRidge.scale.set(0.44, 0.075, 0.19);
  pouchRidge.position.set(1.82, 2.67, 0);
  headGroup.add(pouchRidge);

  // aviator shades
  for (const side of [-1, 1]) {
    const lensMesh = new THREE.Mesh(new THREE.CircleGeometry(0.175, 28), lens);
    lensMesh.scale.y = 0.82;
    lensMesh.position.set(1.23, 2.87, 0.305 * side);
    if (side === -1) lensMesh.rotation.y = Math.PI;
    headGroup.add(lensMesh);

    const rim = new THREE.Mesh(new THREE.TorusGeometry(0.175, 0.018, 8, 28), gold);
    rim.scale.y = 0.82;
    rim.position.copy(lensMesh.position);
    rim.position.z += 0.008 * side;
    if (side === -1) rim.rotation.y = Math.PI;
    headGroup.add(rim);

    const arm = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.02, 0.022), gold);
    arm.position.set(1.06, 2.925, 0.315 * side);
    arm.rotation.y = 0.14 * side;
    headGroup.add(arm);

    const glint = new THREE.Mesh(
      new THREE.CircleGeometry(0.045, 16),
      new THREE.MeshBasicMaterial({ color: "#fff7dc", transparent: true, opacity: 0.75 })
    );
    glint.position.set(1.29, 2.915, 0.317 * side + 0.012 * side);
    if (side === -1) glint.rotation.y = Math.PI;
    headGroup.add(glint);
  }
  const bridge = new THREE.Mesh(new THREE.BoxGeometry(0.022, 0.022, 0.58), gold);
  bridge.position.set(1.24, 2.955, 0);
  headGroup.add(bridge);

  // wings
  const rightWing = createWing(1);
  const leftWing = createWing(-1);
  pelican.add(rightWing.outer, leftWing.outer);

  // tail feathers
  const tail = new THREE.Group();
  tail.position.set(-0.98, 1.58, 0);
  pelican.add(tail);
  for (let i = -2; i <= 2; i++) {
    const feather = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.56, 10), i === 0 ? cream : grey);
    feather.rotation.z = Math.PI / 2 - 0.14;
    feather.scale.z = 0.42;
    feather.position.set(-0.25, 0, 0.09 * i);
    const pivot = new THREE.Group();
    pivot.rotation.y = i * 0.2;
    pivot.rotation.x = 0.1 * i;
    pivot.add(feather);
    tail.add(pivot);
  }

  // legs and webbed feet
  for (const side of [-1, 1]) {
    const hip = new THREE.Vector3(0.03, 1.2, 0.29 * side);
    const knee = new THREE.Vector3(0.22, 0.7, 0.32 * side);
    const ankle = new THREE.Vector3(-0.02, 0.2, 0.33 * side);
    pelican.add(cylinderBetween(hip, knee, 0.055, orange));
    pelican.add(cylinderBetween(knee, ankle, 0.047, orange));
    const joint = new THREE.Mesh(new THREE.SphereGeometry(0.062, 14, 10), orange);
    joint.position.copy(knee);
    pelican.add(joint);

    const foot = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 12), orange);
    foot.scale.set(0.26, 0.045, 0.14);
    foot.position.set(0.13, 0.125, 0.33 * side);
    pelican.add(foot);

    const toe = new THREE.Mesh(new THREE.SphereGeometry(1, 14, 8), pouchMat);
    toe.scale.set(0.15, 0.025, 0.085);
    toe.position.set(0.3, 0.115, 0.33 * side);
    pelican.add(toe);
  }

  const update = (t) => {
    const flap = Math.sin(t * 1.15) * 0.075;
    rightWing.inner.rotation.x = 0.05 + flap;
    leftWing.inner.rotation.x = 0.05 + Math.sin(t * 1.15 + 0.4) * 0.075;
    rightWing.inner.rotation.y = Math.sin(t * 0.7) * 0.04;
    leftWing.inner.rotation.y = -Math.sin(t * 0.7) * 0.04;

    headGroup.position.y = Math.sin(t * 1.15 + 0.6) * 0.025;
    headGroup.rotation.z = Math.sin(t * 0.55) * 0.025;
    pouch.scale.y = 0.24 + Math.sin(t * 2.1) * 0.018;
    pelican.rotation.z = Math.sin(t * 0.8) * 0.014;
  };

  return { group, update, pelican, board };
}

// A small dark silhouette of a distant bird, for a little extra life in the sky.
export function createDistantBird() {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({
    color: "#4c5b60",
    transparent: true,
    opacity: 0.55,
    side: THREE.DoubleSide,
  });
  const wingGeo = new THREE.PlaneGeometry(1, 0.18);
  wingGeo.translate(0.5, 0, 0);
  const l = new THREE.Mesh(wingGeo, mat);
  l.rotation.z = 0.28;
  const r = new THREE.Mesh(wingGeo, mat);
  r.rotation.y = Math.PI;
  r.rotation.z = -0.28;
  g.add(l, r);
  g.userData.wings = [l, r];
  return g;
}

import * as THREE from "three";
import { createOcean, waveHeight, waveNormal } from "./ocean.js";
import { createSurfer, createDistantBird } from "./pelican.js";

const canvas = document.querySelector("#scene");
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: "high-performance" });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2("#e6c6a6", 0.0035);

const camera = new THREE.PerspectiveCamera(38, window.innerWidth / window.innerHeight, 0.1, 1600);
camera.position.set(6.2, 3.8, 8.4);

// ---------------------------------------------------------------- sky
const sunDirection = new THREE.Vector3(-0.42, 0.2, -0.88).normalize();

const sky = new THREE.Mesh(
  new THREE.SphereGeometry(720, 48, 32),
  new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      uSunDir: { value: sunDirection },
      uTop: { value: new THREE.Color("#2c7ea7") },
      uMid: { value: new THREE.Color("#8ac7d9") },
      uHorizon: { value: new THREE.Color("#ffd3a2") },
      uSun: { value: new THREE.Color("#fff2c9") },
    },
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vDir = normalize(wp.xyz - cameraPosition);
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uSunDir;
      uniform vec3 uTop;
      uniform vec3 uMid;
      uniform vec3 uHorizon;
      uniform vec3 uSun;
      varying vec3 vDir;
      void main() {
        vec3 d = normalize(vDir);
        float h = clamp(d.y, 0.0, 1.0);
        vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.26, h));
        col = mix(col, uTop, smoothstep(0.18, 0.72, h));

        float s = max(dot(d, uSunDir), 0.0);
        col += uSun * pow(s, 220.0) * 2.4;
        col += uSun * pow(s, 16.0) * 0.26;
        col += vec3(1.0, 0.62, 0.32) * pow(1.0 - abs(d.y), 22.0) * 0.10 * smoothstep(-0.2, 0.8, dot(d, uSunDir));

        // faint horizontal haze bands
        float haze = sin(d.y * 46.0 + 0.8) * 0.5 + 0.5;
        col = mix(col, uHorizon, smoothstep(0.02, 0.0, d.y) * 0.35 * haze);
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  })
);
sky.renderOrder = -10;
scene.add(sky);

// ---------------------------------------------------------------- light
const hemi = new THREE.HemisphereLight("#bfe8f4", "#0b3b47", 1.15);
scene.add(hemi);

const sun = new THREE.DirectionalLight("#ffe3b0", 2.8);
sun.position.copy(sunDirection).multiplyScalar(60);
sun.position.y += 14;
scene.add(sun);

const rim = new THREE.DirectionalLight("#82c8ff", 1.5);
rim.position.set(14, 10, 22);
scene.add(rim);

const fill = new THREE.DirectionalLight("#ffb98c", 0.55);
fill.position.set(-18, 4, 14);
scene.add(fill);

// ---------------------------------------------------------------- ocean
const ocean = createOcean();
scene.add(ocean.mesh);

// ---------------------------------------------------------------- clouds
function makeCloudTexture() {
  const c = document.createElement("canvas");
  c.width = 512;
  c.height = 256;
  const ctx = c.getContext("2d");
  let seed = 13;
  const rand = () => {
    seed = (seed * 16807) % 2147483647;
    return seed / 2147483647;
  };
  for (let i = 0; i < 34; i++) {
    const x = 70 + rand() * 372;
    const y = 95 + rand() * 70;
    const rx = 32 + rand() * 70;
    const ry = 14 + rand() * 30;
    const g = ctx.createRadialGradient(x, y, 0, x, y, rx);
    const alpha = 0.06 + rand() * 0.09;
    g.addColorStop(0, `rgba(255, 244, 226, ${alpha})`);
    g.addColorStop(0.55, `rgba(255, 236, 214, ${alpha * 0.6})`);
    g.addColorStop(1, "rgba(255, 236, 214, 0)");
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(1, ry / rx);
    ctx.translate(-x, -y);
    ctx.fillStyle = g;
    ctx.fillRect(x - rx, y - rx, rx * 2, rx * 2);
    ctx.restore();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const cloudTexture = makeCloudTexture();
const cloudData = [
  [-140, 44, -260, 210, 66, 0.72],
  [-40, 58, -300, 260, 76, 0.5],
  [120, 38, -280, 190, 52, 0.62],
  [235, 64, -230, 180, 60, 0.34],
  [-250, 72, -160, 200, 62, 0.4],
  [200, 92, -120, 150, 44, 0.26],
];
for (const [x, y, z, w, h, o] of cloudData) {
  const mat = new THREE.SpriteMaterial({
    map: cloudTexture,
    color: "#ffe9cd",
    transparent: true,
    opacity: o,
    depthWrite: false,
    fog: false,
  });
  const sprite = new THREE.Sprite(mat);
  sprite.position.set(x, y, z);
  sprite.scale.set(w, h, 1);
  scene.add(sprite);
}

// ---------------------------------------------------------------- surfer
const surfer = createSurfer();
scene.add(surfer.group);

// foam collar where the board meets the water
const collar = new THREE.Mesh(
  new THREE.RingGeometry(0.72, 1.18, 48),
  new THREE.MeshBasicMaterial({
    color: "#fff6e3",
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
    side: THREE.DoubleSide,
  })
);
collar.rotation.x = -Math.PI / 2;
collar.scale.set(1.25, 0.48, 1);
scene.add(collar);

// ---------------------------------------------------------------- spray
function makeSoftDisc() {
  const c = document.createElement("canvas");
  c.width = 64;
  c.height = 64;
  const ctx = c.getContext("2d");
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.35, "rgba(255,250,235,0.85)");
  g.addColorStop(1, "rgba(255,250,235,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const sprayCount = 320;
const sprayPositions = new Float32Array(sprayCount * 3);
const sprayData = Array.from({ length: sprayCount }, () => ({
  life: 0,
  max: 1,
  vel: new THREE.Vector3(),
}));

const sprayGeo = new THREE.BufferGeometry();
sprayGeo.setAttribute("position", new THREE.BufferAttribute(sprayPositions, 3));
const sprayMat = new THREE.PointsMaterial({
  map: makeSoftDisc(),
  color: "#fff7e9",
  size: 0.16,
  transparent: true,
  opacity: 0.95,
  depthWrite: false,
  blending: THREE.NormalBlending,
  sizeAttenuation: true,
});
const spray = new THREE.Points(sprayGeo, sprayMat);
spray.frustumCulled = false;
scene.add(spray);

const worldTail = new THREE.Vector3();
const worldNose = new THREE.Vector3();
const tailLocal = new THREE.Vector3(-1.95, 0.1, 0);
const noseLocal = new THREE.Vector3(2.35, 0.1, 0);

let spawnAccumulator = 0;

function spawnParticle(tailOrNose, spread, upSpeed) {
  const idx = sprayData.findIndex((p) => p.life <= 0);
  if (idx === -1) return;
  const p = sprayData[idx];
  p.max = 0.55 + Math.random() * 0.65;
  p.life = p.max;
  const src = tailOrNose === "nose" ? worldNose : worldTail;
  sprayPositions[idx * 3] = src.x + (Math.random() - 0.5) * 0.5;
  sprayPositions[idx * 3 + 1] = src.y + Math.random() * 0.18;
  sprayPositions[idx * 3 + 2] = src.z + (Math.random() - 0.5) * spread;
  p.vel.set(
    -1.6 - Math.random() * 3.2,
    upSpeed + Math.random() * 1.8,
    (Math.random() - 0.5) * 2.0
  );
}

function updateSpray(dt) {
  for (let i = 0; i < sprayCount; i++) {
    const p = sprayData[i];
    if (p.life > 0) {
      p.life -= dt;
      p.vel.y -= 7.0 * dt;
      sprayPositions[i * 3] += p.vel.x * dt;
      sprayPositions[i * 3 + 1] += p.vel.y * dt;
      sprayPositions[i * 3 + 2] += p.vel.z * dt;
      if (p.life <= 0) {
        sprayPositions[i * 3 + 1] = -50;
      }
    }
  }
  sprayGeo.attributes.position.needsUpdate = true;
}

// ---------------------------------------------------------------- distant birds
const birdData = [
  { pos: new THREE.Vector3(-20, 9, -38), scale: 1.4, phase: 0, speed: 0.9 },
  { pos: new THREE.Vector3(-13, 11, -44), scale: 1.05, phase: 1.7, speed: 1.1 },
  { pos: new THREE.Vector3(24, 8, -46), scale: 1.2, phase: 3.1, speed: 0.8 },
];
const birds = birdData.map((d) => {
  const b = createDistantBird();
  b.position.copy(d.pos);
  b.scale.setScalar(d.scale);
  b.userData = { ...b.userData, ...d };
  scene.add(b);
  return b;
});

// ---------------------------------------------------------------- animation
const clock = new THREE.Clock();
let elapsed = 0;

function animate() {
  const dt = Math.min(clock.getDelta(), 0.05);
  elapsed += dt;
  const t = elapsed;

  ocean.update(t);
  surfer.update(t);

  // board rides the surface
  const bx = Math.sin(t * 0.31) * 0.28;
  const bz = Math.sin(t * 0.22 + 1.1) * 0.16;
  const y = waveHeight(bx, bz, t) + 0.1;
  const n = waveNormal(bx, bz, t);
  surfer.group.position.set(bx, y, bz);
  surfer.group.rotation.order = "YXZ";
  surfer.group.rotation.y = Math.sin(t * 0.24) * 0.075 + 0.02;
  surfer.group.rotation.x = Math.atan2(n.z, n.y);
  surfer.group.rotation.z = Math.atan2(-n.x, n.y) + Math.sin(t * 0.7) * 0.015;
  surfer.group.position.y += Math.sin(t * 1.9) * 0.025;

  surfer.group.updateMatrixWorld();

  worldTail.copy(tailLocal).applyMatrix4(surfer.group.matrixWorld);
  worldNose.copy(noseLocal).applyMatrix4(surfer.group.matrixWorld);

  spawnAccumulator += dt * 105;
  while (spawnAccumulator > 1) {
    spawnAccumulator -= 1;
    spawnParticle(Math.random() < 0.82 ? "tail" : "nose", 1.1, 2.0);
  }
  updateSpray(dt);

  collar.position.set(bx, y - 0.08, bz);
  collar.rotation.z = surfer.group.rotation.y;
  collar.material.opacity = 0.24 + Math.sin(t * 1.7) * 0.06;

  // birds drift and flap
  for (const b of birds) {
    const d = b.userData;
    b.position.x = d.pos.x + Math.sin(t * 0.12 * d.speed + d.phase) * 11;
    b.position.z = d.pos.z + Math.cos(t * 0.1 * d.speed + d.phase) * 6;
    b.position.y = d.pos.y + Math.sin(t * 0.5 + d.phase) * 0.6;
    b.rotation.y = -Math.sin(t * 0.12 * d.speed + d.phase) * 0.5;
    const flap = Math.sin(t * 5.2 * d.speed + d.phase) * 0.5;
    const wings = b.userData.wings;
    if (wings) {
      wings[0].rotation.z = 0.28 + flap;
      wings[1].rotation.z = -0.28 - flap;
    }
  }

  // slow, cinematic camera drift
  const angle = 0.64 + Math.sin(t * 0.065) * 0.14;
  const radius = 10.9 + Math.sin(t * 0.11) * 0.55;
  camera.position.set(
    Math.sin(angle) * radius,
    3.65 + Math.sin(t * 0.17) * 0.32,
    Math.cos(angle) * radius
  );
  camera.lookAt(0.15, 1.95 + Math.sin(t * 0.35) * 0.06, 0);

  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
}
window.addEventListener("resize", onResize);

animate();

:root {
  --cream: #fff4dd;
  --cream-soft: rgba(255, 244, 221, 0.72);
  --ink: #12333a;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0a4659;
  color: var(--cream);
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.vignette,
.grain,
.frame {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

.vignette {
  background:
    radial-gradient(140% 100% at 52% 36%, rgba(0, 0, 0, 0) 42%, rgba(1, 25, 32, 0.3) 100%),
    linear-gradient(180deg, rgba(0, 28, 38, 0.08) 0%, rgba(0, 0, 0, 0) 30%, rgba(0, 23, 30, 0.3) 100%);
}

.grain {
  opacity: 0.16;
  mix-blend-mode: soft-light;
  background-image:
    radial-gradient(rgba(255, 255, 255, 0.7) 0.5px, transparent 0.6px),
    radial-gradient(rgba(0, 0, 0, 0.55) 0.5px, transparent 0.6px);
  background-size: 3px 3px, 4px 4px;
  background-position: 0 0, 1px 2px;
}

.frame {
  inset: 18px;
  border: 1px solid rgba(255, 242, 218, 0.28);
}

.frame::before,
.frame::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 6px;
  background: var(--cream);
  opacity: 0.7;
}

.frame::before {
  top: -3.5px;
  left: -3.5px;
}
.frame::after {
  bottom: -3.5px;
  right: -3.5px;
}

.masthead {
  position: fixed;
  top: 38px;
  left: 42px;
  right: 42px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  pointer-events: none;
  font-size: 10px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--cream-soft);
  text-shadow: 0 1px 10px rgba(4, 35, 42, 0.45);
}

.mark {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mark-dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border: 1px solid var(--cream-soft);
  border-radius: 50%;
  position: relative;
}

.mark-dot::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  background: var(--cream);
  opacity: 0.85;
}

.coords {
  font-variant-numeric: tabular-nums;
}

.overlay {
  position: fixed;
  left: 52px;
  bottom: 64px;
  width: min(520px, 48vw);
  pointer-events: none;
}

.eyebrow {
  margin: 0 0 14px;
  font-size: 10px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--cream-soft);
  display: flex;
  align-items: center;
  gap: 12px;
}

.eyebrow::before {
  content: "";
  width: 34px;
  height: 1px;
  background: rgba(255, 244, 221, 0.55);
}

.title {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
  font-size: clamp(48px, 6.4vw, 92px);
  line-height: 0.92;
  letter-spacing: -0.025em;
  color: var(--cream);
  text-shadow: 0 2px 30px rgba(2, 28, 35, 0.35);
}

.title em {
  font-style: italic;
  font-weight: 400;
  font-size: 0.84em;
  letter-spacing: -0.01em;
  color: var(--cream);
}

.rule {
  width: 72px;
  height: 1px;
  margin: 20px 0 18px;
  background: rgba(255, 244, 221, 0.5);
}

.caption {
  margin: 0;
  font-size: 12px;
  line-height: 1.8;
  letter-spacing: 0.06em;
  color: rgba(255, 244, 221, 0.7);
  max-width: 340px;
}

.footer {
  position: fixed;
  bottom: 38px;
  left: 42px;
  right: 42px;
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: rgba(255, 244, 221, 0.55);
  pointer-events: none;
}

.footer span:first-child {
  margin-left: 290px;
}

.reveal {
  opacity: 0;
  transform: translateY(12px);
  animation: rise 1.5s cubic-bezier(0.16, 0.72, 0.25, 1) forwards;
}

.d1 {
  animation-delay: 0.25s;
}
.d2 {
  animation-delay: 0.4s;
}
.d3 {
  animation-delay: 0.62s;
}
.d4 {
  animation-delay: 0.78s;
}
.d5 {
  animation-delay: 0.95s;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 760px) {
  .frame {
    inset: 10px;
  }
  .masthead {
    top: 24px;
    left: 22px;
    right: 22px;
  }
  .coords {
    display: none;
  }
  .overlay {
    left: 24px;
    bottom: 52px;
    width: calc(100vw - 48px);
  }
  .title {
    font-size: clamp(44px, 14vw, 68px);
  }
  .caption {
    display: none;
  }
  .footer {
    left: 22px;
    right: 22px;
    bottom: 22px;
  }
  .footer span:first-child {
    margin-left: 0;
  }
}

